// TEST ONLY — a loopback SMTP server for adapter tests and the isolated C10 acceptance chain.
// Speaks implicit TLS (465 style) or STARTTLS (587 style) with a throwaway CA generated by `openssl`
// into a temp directory per run (no key material is stored in Git). Never used by deployed functions.
import net from "node:net";
import tls from "node:tls";

export interface TestPki {
  caPem: string;
  certPem: string;
  keyPem: string;
  cleanup(): Promise<void>;
}

/** Creates a throwaway CA + 127.0.0.1/localhost leaf certificate. Needs --allow-run=openssl and temp read/write. */
export async function makeTestPki(): Promise<TestPki> {
  const dir = await Deno.makeTempDir({ prefix: "gina-c10-smtp-" });
  const run = async (args: string[]) => {
    const out = await new Deno.Command("openssl", { args, cwd: dir, stdout: "null", stderr: "piped" }).output();
    if (!out.success) throw new Error("openssl_failed:" + args[0]);
  };
  await run(["req", "-x509", "-newkey", "ec", "-pkeyopt", "ec_paramgen_curve:P-256", "-nodes", "-keyout", "ca.key", "-out", "ca.pem", "-days", "1", "-subj", "/CN=GINA C10 test CA"]);
  await run(["req", "-newkey", "ec", "-pkeyopt", "ec_paramgen_curve:P-256", "-nodes", "-keyout", "leaf.key", "-out", "leaf.csr", "-subj", "/CN=localhost"]);
  await Deno.writeTextFile(`${dir}/leaf.ext`, "subjectAltName=IP:127.0.0.1,DNS:localhost\nbasicConstraints=CA:FALSE\nkeyUsage=digitalSignature\nextendedKeyUsage=serverAuth\n");
  await run(["x509", "-req", "-in", "leaf.csr", "-CA", "ca.pem", "-CAkey", "ca.key", "-CAcreateserial", "-out", "leaf.pem", "-days", "1", "-extfile", "leaf.ext"]);
  const [caPem, certPem, keyPem] = await Promise.all(["ca.pem", "leaf.pem", "leaf.key"].map((f) => Deno.readTextFile(`${dir}/${f}`)));
  return { caPem, certPem, keyPem, cleanup: () => Deno.remove(dir, { recursive: true }) };
}

export interface CapturedMail {
  from: string;
  to: string;
  data: string;
}
export interface FakeSmtpOptions {
  mode: "tls" | "starttls";
  pki: TestPki;
  /** starttls only: answer STARTTLS with 454 (simulates a stripped/refused upgrade). */
  refuseStartTls?: boolean;
}
export interface FakeSmtp {
  port: number;
  /** Every client command with whether it arrived over TLS; AUTH is redacted. */
  transcript: { line: string; tls: boolean }[];
  mails: CapturedMail[];
  close(): Promise<void>;
}

export function startFakeSmtp(o: FakeSmtpOptions): Promise<FakeSmtp> {
  const transcript: FakeSmtp["transcript"] = [];
  const mails: CapturedMail[] = [];
  const context = tls.createSecureContext({ cert: o.pki.certPem, key: o.pki.keyPem });
  const sockets = new Set<net.Socket>();

  function serve(socket: net.Socket, secure: boolean, greet: boolean) {
    sockets.add(socket);
    socket.on("close", () => sockets.delete(socket));
    socket.on("error", () => undefined);
    let buffer = "", inData = false, from = "", to = "", upgraded = false;
    const write = (s: string) => socket.write(s + "\r\n");
    if (greet) write("220 fake.example.invalid ESMTP");
    const onData = (chunk: Buffer) => {
      if (upgraded) return;
      buffer += chunk.toString("utf8");
      for (;;) {
        if (inData) {
          const end = buffer.indexOf("\r\n.\r\n");
          if (end < 0) return;
          mails.push({ from, to, data: buffer.slice(0, end) });
          buffer = buffer.slice(end + 5);
          inData = false;
          write(`250 2.0.0 Ok: queued as FAKE${mails.length}`);
          continue;
        }
        const nl = buffer.indexOf("\r\n");
        if (nl < 0) return;
        const line = buffer.slice(0, nl);
        buffer = buffer.slice(nl + 2);
        transcript.push({ line: line.startsWith("AUTH") ? "AUTH <redacted>" : line, tls: secure });
        if (line.startsWith("EHLO")) {
          write("250-fake.example.invalid");
          if (o.mode === "starttls" && !secure) write("250-STARTTLS");
          write("250 AUTH PLAIN");
        } else if (line === "STARTTLS" && o.mode === "starttls" && !secure) {
          if (o.refuseStartTls) {
            write("454 4.7.0 TLS not available");
            continue;
          }
          write("220 2.0.0 Ready to start TLS");
          upgraded = true;
          socket.removeListener("data", onData);
          const tlsSocket = new tls.TLSSocket(socket, { isServer: true, secureContext: context });
          serve(tlsSocket, true, false);
          return;
        } else if (line.startsWith("AUTH")) write("235 2.7.0 ok");
        else if (line.startsWith("MAIL FROM:")) {
          from = line.slice(10).replace(/[<>]/g, "");
          write("250 ok");
        } else if (line.startsWith("RCPT TO:")) {
          to = line.slice(8).replace(/[<>]/g, "");
          write("250 ok");
        } else if (line === "DATA") {
          inData = true;
          write("354 go ahead");
        } else if (line === "QUIT") {
          write("221 bye");
          socket.end();
          return;
        } else write("250 ok");
      }
    };
    socket.on("data", onData);
  }

  const server = o.mode === "tls"
    ? tls.createServer({ cert: o.pki.certPem, key: o.pki.keyPem }, (s) => serve(s, true, true))
    : net.createServer((s) => serve(s, false, true));
  return new Promise((resolve) => {
    server.listen(0, "127.0.0.1", () => {
      const port = (server.address() as net.AddressInfo).port;
      resolve({
        port,
        transcript,
        mails,
        close: () =>
          new Promise<void>((done) => {
            for (const s of sockets) s.destroy();
            server.close(() => done());
          }),
      });
    });
  });
}

/** Decodes the base64 text/plain body the GINA SMTP adapter writes. */
export function decodeBody(data: string): { headers: string; text: string } {
  const split = data.indexOf("\r\n\r\n");
  const headers = data.slice(0, split);
  const b64 = data.slice(split + 4).replace(/\r\n/g, "").replace(/^\.\./gm, ".");
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  return { headers, text: new TextDecoder().decode(bytes) };
}
